import sys

def eventualSafeNodes(V, adj):
    def dfs(node):
        if visited[node] == 1:
            return False
        if visited[node] == 2:
            return True
        visited[node] = 1
        for neighbor in adj[node]:
            if not dfs(neighbor):
                return False
        visited[node] = 2
        return True

    visited = [0] * V
    safe_nodes = []
    for i in range(V):
        if dfs(i):
            safe_nodes.append(i)
    return safe_nodes

def main():
    import sys
    input = sys.stdin.read().split()
    V = int(input[0])
    E = int(input[1])
    adj = [[] for _ in range(V)]
    index = 2
    for _ in range(E):
        u = int(input[index])
        v = int(input[index + 1])
        adj[u].append(v)
        index += 2
    safe_nodes = eventualSafeNodes(V, adj)
    print(' '.join(map(str, sorted(safe_nodes))))

if __name__ == "__main__":
    main()
